    ]

    month_map = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
                 'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}

    for pattern, format_type in date_patterns:
        matches = re.finditer(pattern, text, re.IGNORECASE)
        for match in matches:
            try:
                groups = match.groups()
                if len(groups) == 3:
                    if format_type == 'YYYY-MM-DD':
                        date_obj = datetime(int(groups[0]), int(groups[1]), int(groups[2]))
                    elif format_type == 'DD-MM-YYYY':
                        date_obj = datetime(int(groups[2]), int(groups[1]), int(groups[0]))
                    elif format_type == 'DD Mon YYYY':
                        month = month_map.get(groups[1][:3].lower())
                        if month:
                            date_obj = datetime(int(groups[2]), month, int(groups[0]))
                        else:
                            continue
                    elif format_type == 'Mon DD YYYY':
                        month = month_map.get(groups[0][:3].lower())
                        if month:
                            date_obj = datetime(int(groups[2]), month, int(groups[1]))
                        else:
                            continue
                    elif format_type == 'DD-MM-YY':
                        # Assume 2-digit year: 00-49 -> 2000-2049, 50-99 -> 1950-1999
                        year = int(groups[2])
                        full_year = 2000 + year if year < 50 else 1900 + year
                        date_obj = datetime(full_year, int(groups[1]), int(groups[0]))
                    elif format_type == 'DD Mon YY':
                        month = month_map.get(groups[1][:3].lower())
                        if month:
                            year = int(groups[2])
                            full_year = 2000 + year if year < 50 else 1900 + year
                            date_obj = datetime(full_year, month, int(groups[0]))
                        else:
                            continue
                    else:
                        continue

                    # Validate date is reasonable (between 2000 and 2030)
                    if 2000 <= date_obj.year <= 2030:
                        return date_obj.strftime('%Y-%m-%d')
            except (ValueError, IndexError):
                continue

    return None

def parse_total_amount(text):
    """Extract total amount from OCR text using priority keywords"""
    lines = text.split('\n')

    # Exclusion keywords
    exclusion_keywords = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    # Priority keyword groups (in order of priority)
    keyword_groups = [
        ['GRAND TOTAL'],
        ['TOTAL RM', 'TOTAL: RM'],
        ['TOTAL AMOUNT'],
        ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
    ]

    # Pattern to match monetary values - more flexible
    money_pattern = r'(?:RM)?\s*([\d,]+\.\d{2})'

    for keyword_list in keyword_groups:
        for i, line in enumerate(lines):
            line_upper = line.upper()

            # Check if line contains exclusion keywords
            if any(excl in line_upper for excl in exclusion_keywords):
                continue

            # Check if line contains any keyword from current priority group
            for keyword in keyword_list:
                if keyword in line_upper:
                    # Try to find amount on the same line
                    match = re.search(money_pattern, line)
                    if match:
                        amount_str = match.group(1).replace(',', '')
                        try:
                            amount = float(amount_str)
                            return f"{amount:.2f}"
                        except ValueError:
                            pass

                    # If not found on same line, check next line
                    if i + 1 < len(lines):
                        next_line = lines[i + 1]
                        match = re.search(money_pattern, next_line)
                        if match:
                            amount_str = match.group(1).replace(',', '')
                            try:
                                amount = float(amount_str)
                                return f"{amount:.2f}"
                            except ValueError:
                                pass

    return None

def process_receipts(img_dir, output_file):
    """Process all receipt images and create Excel file"""
    # Get all image files and sort by filename
    image_files = [f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png'))]
    image_files.sort()

    results = []

    for filename in image_files:
        print(f"Processing {filename}...")
        img_path = os.path.join(img_dir, filename)

        # Extract text
        text = extract_text_from_image(img_path)

        # Parse date and total amount
        date = parse_date(text)
        total_amount = parse_total_amount(text)

        results.append({
            'filename': filename,
            'date': date,
            'total_amount': total_amount
        })

        print(f"  Date: {date}, Total: {total_amount}")

    # Create Excel file
    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    # Write header
    ws.append(['filename', 'date', 'total_amount'])

    # Write data
    for result in results:
        ws.append([result['filename'], result['date'], result['total_amount']])

    # Save workbook
    wb.save(output_file)
    print(f"\nResults saved to {output_file}")

if __name__ == "__main__":
    img_dir = "/app/workspace/dataset/img"
    output_file = "/app/workspace/stat_ocr.xlsx"
    process_receipts(img_dir, output_file)
